// The altitude to the hypotenuse splits a right triangle into two triangles, each
// similar to the whole. Two-argument size() fixes the output box, so the declared
// ratio 1.286 is exact.
size(360,280);
pen l = black + 1.3;
pen g = gray(0.55) + 1;
pair A = (3,4);
pair B = (-3,0);
pair C = (3,0);
pair D = (1.15,2.77);
dot(A,l);
dot(B,l);
dot(C,l);
dot(D,black+2pt);
draw(A--B--C--cycle, l);
draw(C--D, g);
draw((2.6,0)--(2.6,0.4)--(3,0.4), black+0.9pt);
draw(D--(1.32,2.52)--(1.40,2.94), black+0.9pt);
label("$A$", A, NE);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, NW);
label("$CD$", (2.1,1.5), SE);
label("$AB$", (0.2,2.0), NW);
label("each small triangle is similar to $\\triangle ABC$", (0,-1.5), S);

// Two triangles of the same shape at different sizes, with the corresponding
// vertices named. Two-argument size() fixes the output box, so the declared ratio
// 1.667 is exact.
size(400,240);
pen l = black + 1.3;
pair A1 = (0,3.6);
pair B1 = (-2.2,0);
pair C1 = (2.2,0);
pair A2 = (4.8,4.2);
pair B2 = (1.4,0);
pair C2 = (7.0,0);
draw(A1--B1--C1--cycle, l);
draw(A2--B2--C2--cycle, l);
label("$A$", A1, NE);
label("$B$", B1, SW);
label("$C$", C1, S);
label("$D$", A2, NE);
label("$E$", B2, SW);
label("$F$", C2, S);
label("small", (0,-1.1), S);
label("large", (4.7,-1.1), S);
label("corresponding vertices sit in the same order", (2.6,-2.0), S);

// A segment parallel to the base cuts off a smaller triangle of the same shape.
// Two-argument size() fixes the output box, so the declared ratio 1.067 is exact.
size(320,300);
pen l = black + 1.3;
pen p = gray(0.55) + 1.2;
pair A = (1.6,5.0);
pair B = (0,0);
pair C = (5.0,0);
pair D = (0.8,2.5);
pair E = (3.1,2.5);
draw(A--B--C--cycle, l);
draw(D--E, p);
dot(A,l);
dot(B,l);
dot(C,l);
dot(D,l);
dot(E,l);
label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, W);
label("$E$", E, E);
label("$DE \parallel BC$", (2.4,1.1), SE);
label("$\\triangle ADE \\sim \\triangle ABC$", (2.5,-0.9), S);

// An isosceles trapezoid, with the two end right triangles that read off the
// height. Two-argument size() fixes the output box, so the declared ratio 1.385
// is exact.
size(360,260);
pen l = black + 1.3;
pen d = gray(0.55) + 1.1;
pair A = (-1.5,3.4);
pair B = (1.5,3.4);
pair C = (3.9,0);
pair D = (-3.9,0);
pair P = (-1.5,0);
pair Q = (1.5,0);
draw(A--B--C--D--cycle, l);
draw(A--P, d);
draw(B--Q, d);
draw(P--Q, d);
dot(A,l);
dot(B,l);
dot(C,l);
dot(D,l);
dot(P,l);
dot(Q,l);
label("$A$", A, NW);
label("$B$", B, NE);
label("$C$", C, SE);
label("$D$", D, SW);
label("$P$", P, S);
label("$Q$", Q, S);
label("equal legs give equal base angles", (0,-1.1), S);
label("$\\angle A = \\angle B$", (0,4.1), N);
